          a: { type: 'number', description: 'First operand (numeric).' },
          b: { type: 'number', description: 'Second operand (numeric).' },
          operation: {
            type: 'string',
            enum: ['add', 'subtract', 'multiply', 'divide'],
            description: 'Arithmetic operation to perform on a and b.',
          },
        },
        required: REQUIRED_FIELDS,
        additionalProperties: false,
      },
    },
  ];
}

function isFiniteNumber(value) {
  return typeof value === 'number' && Number.isFinite(value);
}

function validateArgs(args) {
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Invalid arguments: expected an object.');
  }

  for (const field of REQUIRED_FIELDS) {
    if (!(field in args)) {
      throw new Error(`Invalid arguments: missing required field "${field}".`);
    }
  }

  for (const key of Object.keys(args)) {
    if (!REQUIRED_FIELDS.includes(key)) {
      throw new Error(`Invalid arguments: unexpected field "${key}".`);
    }
  }

  if (!isFiniteNumber(args.a)) {
    throw new Error('Invalid arguments: "a" must be a finite number.');
  }
  if (!isFiniteNumber(args.b)) {
    throw new Error('Invalid arguments: "b" must be a finite number.');
  }

  if (typeof args.operation !== 'string' || !SUPPORTED_OPS.has(args.operation)) {
    throw new Error(
      `Invalid arguments: "operation" must be one of ${[...SUPPORTED_OPS].join(', ')}.`
    );
  }

  if (args.operation === 'divide' && args.b === 0) {
    throw new Error('Invalid arguments: division by zero is not allowed.');
  }
}

function compute(a, b, operation) {
  switch (operation) {
    case 'add':
      return a + b;
    case 'subtract':
      return a - b;
    case 'multiply':
      return a * b;
    case 'divide':
      return a / b;
    default:
      throw new Error(`Unsupported operation: ${operation}`);
  }
}

export async function callTool(name, args) {
  if (name !== TOOL_NAME) {
    throw new Error(`Unknown tool: ${name}`);
  }

  validateArgs(args ?? {});

  const { a, b, operation } = args;
  const result = compute(a, b, operation);

  const text = Number.isInteger(result) ? String(result) : String(result);
  return { content: [{ type: 'text', text }] };
